						},
						Idx = 12,
						ShowConditions = {
							PlaceObj('QuestIsVariableBool', {
								QuestId = "U-Bahn",
								Vars = set( "MentionProject" ),
							}),
						},
						Text = T(365091580605, --[[ModItemQuestsDef U-Bahn Text]] "The underground <em>railroad</em> connects a system of Labs built by the Nazi for the completion of the mysterious <em>Projekt Eisdrache</em>"),
